# AI-generated (Claude), 2026-11-07: rewritten for the MSIX package data folder (README.md §5, §16).

<#
.SYNOPSIS
    Resets SecretLead to first-run state.

.DESCRIPTION
    Deletes every stored entity (<EntityName>.md / <EntityName>.txt) from
    SecretLead's data folder. Existence-of-file is the whole mechanism
    SecretLead uses to know what entities exist (README.md §6), so removing
    these files is a complete, clean reset -- there's no other index, cache,
    or database tracking anything. The next launch adds the Construction demo
    again (README.md §11).

    SecretLead is an MSIX package. It keeps its records in its package data
    folder (ApplicationData.Current.LocalFolder):
        %LOCALAPPDATA%\Packages\<PackageFamilyName>\LocalState
    The script finds every installed SecretLead package for the current user
    by its package name (Identity Name in SecretLead.UI/Package.appxmanifest).
    That name doesn't change when the publisher does, so a developer build and
    a signed release are both found, each with its own data folder.

    Only .md and .txt files directly in each data folder are deleted.

.PARAMETER Force
    Skip the confirmation prompt.

.EXAMPLE
    .\scripts\Reset-SecretLeadAppData.ps1

.EXAMPLE
    .\scripts\Reset-SecretLeadAppData.ps1 -Force

.NOTES
    Close SecretLead first.
    If Windows blocks this script ("running scripts is disabled on this
    system"), either right-click the file > Properties > Unblock, or run:
        powershell -ExecutionPolicy Bypass -File .\scripts\Reset-SecretLeadAppData.ps1
#>
[CmdletBinding(SupportsShouldProcess, ConfirmImpact = 'High')]
param(
    [switch]$Force
)

# Identity Name in SecretLead.UI/Package.appxmanifest.
$packageName = 'D3B25905-54E0-4737-BC59-F1CFA9E25E2B'

$packages = @(Get-AppxPackage -Name $packageName)
if ($packages.Count -eq 0) {
    Write-Host "SecretLead isn't installed for this user -- nothing to reset."
    exit 0
}

if (Get-Process -Name 'SecretLead.UI' -ErrorAction SilentlyContinue) {
    Write-Warning "SecretLead is running. Close it, then run this script again."
    exit 1
}

foreach ($package in $packages) {
    $dataFolder = Join-Path $env:LOCALAPPDATA "Packages\$($package.PackageFamilyName)\LocalState"
    Write-Host "SecretLead $($package.Version), publisher $($package.Publisher)"

    if (-not (Test-Path -LiteralPath $dataFolder)) {
        Write-Host "  No data folder at $dataFolder -- nothing to reset."
        continue
    }

    $files = @(Get-ChildItem -LiteralPath $dataFolder -File | Where-Object { $_.Extension -in '.md', '.txt' })
    if ($files.Count -eq 0) {
        Write-Host "  $dataFolder is already empty -- nothing to reset."
        continue
    }

    Write-Host "  Found $($files.Count) file(s) in $dataFolder :"
    $files | ForEach-Object { Write-Host "    $($_.Name)" }

    if ($Force -or $PSCmdlet.ShouldProcess($dataFolder, "Delete $($files.Count) file(s)")) {
        $files | Remove-Item -Force
        Write-Host "  Done. SecretLead will add the Construction demo again on next launch."
    }
}
